// The DOT twin of rToFixedFenced: `n.toFixed(2)` on a checked-dynamic number
// has no static lowering. Its own package, because a refused function poisons
// the whole module that holds it and keyedstrnum is a program that must build.
"use strict";
function t(f) { try { return String(f()); } catch (e) { return "THREW " + String(e && e.message); } }
function dfrac() { return JSON.parse("1.5"); }
exports.rToFixedDot = function () { var n = dfrac(); return t(function () { return n.toFixed(2); }); };
